import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { $, browser } from '@wdio/globals';

const OUT = process.env.UT_OUT as string;
const invoke = (cmd: string, args: object): Promise<unknown> =>
  browser.executeAsync(
    (c: string, a: object, done: (r: unknown) => void) => {
      (window as any).__TAURI_INTERNALS__.invoke(c, a).then((r: unknown) => done({ ok: r }), (e: unknown) => done({ err: String(e) }));
    },
    cmd,
    args,
  );

describe('ut-m5 run C', () => {
  it('opens mission live from the library store with telemetry on', async () => {
    mkdirSync(OUT, { recursive: true });
    await browser.refresh();
    await $('[data-testid="open-path"]').waitForDisplayed({ timeout: 30_000 });
    const missions: any = await invoke('list_missions', {});
    writeFileSync(join(OUT, 'list_missions.json'), JSON.stringify(missions, null, 2));
    const row = missions.ok.find((r: any) => r.name === 'live') ?? missions.ok[0];
    const opened: any = await invoke('open_mission', { mission_id: row.id });
    writeFileSync(join(OUT, 'open_mission-summary.json'), JSON.stringify({ err: opened.err, events: opened.ok?.events?.length }, null, 2));
    writeFileSync(join(OUT, 'telemetry_status.json'), JSON.stringify(await invoke('telemetry_status', {}), null, 2));
    await browser.pause(50_000);
  });
});
EOF
